before.lib/job.ex:
defmodule Job do
  defstruct [:name, :status]
  @doc "Build a ready job with a trimmed nonempty name."
  def new(name) do
    case String.trim(name) do
      "" -> {:error, :empty}
      name -> {:ok, %__MODULE__{name: name, status: :ready}}
    end
  end
end

